1	export type Cell = [x: number, y: number];
2	
3	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
4	  x === otherX && y === otherY;
5	
6	const isNeighbourOf = (cell: Cell, candidate: Cell): boolean =>
7	  !isSameCell(cell, candidate) &&
8	  Math.abs(candidate[0] - cell[0]) <= 1 &&
9	  Math.abs(candidate[1] - cell[1]) <= 1;
10	
11	const countLiveNeighbours = (cell: Cell, liveCells: Cell[]): number =>
12	  liveCells.filter((candidate) => isNeighbourOf(cell, candidate)).length;
13	
14	const isAlive = (cell: Cell, liveCells: Cell[]): boolean =>
15	  liveCells.some((liveCell) => isSameCell(cell, liveCell));
16	
17	const isAliveNextGeneration = (cell: Cell, liveCells: Cell[]): boolean => {
18	  const neighbours = countLiveNeighbours(cell, liveCells);
19	
20	  return isAlive(cell, liveCells)
21	    ? neighbours === 2 || neighbours === 3
22	    : neighbours === 3;
23	};
24	
25	const NEIGHBOUR_OFFSETS = [-1, 0, 1];
26	
27	const cellKey = ([x, y]: Cell): string => `${x},${y}`;
28	
29	const cellWithSurroundingBox = ([x, y]: Cell): Cell[] =>
30	  NEIGHBOUR_OFFSETS.flatMap((offsetX) =>
31	    NEIGHBOUR_OFFSETS.map((offsetY): Cell => [x + offsetX, y + offsetY]),
32	  );
33	
34	const deduplicated = (cells: Cell[]): Cell[] => [
35	  ...new Map(cells.map((cell) => [cellKey(cell), cell])).values(),
36	];
37	
38	const cellsToEvaluate = (liveCells: Cell[]): Cell[] =>
39	  deduplicated(liveCells.flatMap(cellWithSurroundingBox));
40	
41	export function nextGeneration(liveCells: Cell[]): Cell[] {
42	  return cellsToEvaluate(liveCells).filter((cell) =>
43	    isAliveNextGeneration(cell, liveCells),
44	  );
45	}
