7	describe("Game of Life - next generation", () => {
8	  it("should return an empty grid for an empty grid — [] → []", () => {
9	    expect(nextGeneration([])).toEqual([]);
10	  });
11	  it("should kill a single lone cell (0 neighbors) — [(0,0)] → []", () => {
12	    expect(nextGeneration([[0, 0]])).toEqual([]);
13	  });
14	  it("Rule 1 Underpopulation: should kill both cells that have 1 neighbor each — [(0,1), (1,1)] → []", () => {
15	    expect(
16	      nextGeneration([
17	        [0, 1],
18	        [1, 1],
19	      ]),
20	    ).toEqual([]);
21	  });
22	  it("Rule 2 Survival: should keep a live cell with 3 live neighbors alive — center (1,1) survives", () => {
23	    // Gen 0: ### on the top row, plus the live centre cell (1,1).
24	    // (1,1) is live and has exactly 3 live neighbours: (0,0), (1,0), (2,0).
25	    const result = nextGeneration([
26	      [0, 0],
27	      [1, 0],
28	      [2, 0],
29	      [1, 1],
30	    ]);
31	
32	    expect(result).toContainEqual([1, 1]);
33	  });
34	  it("Rule 3 Overpopulation: should kill a live cell with 4 live neighbors — center (1,1) dies", () => {
35	    // Gen 0: the live centre (1,1) surrounded by the four corners of its
36	    // 3x3 box, giving it exactly 4 live neighbours.
37	    const result = nextGeneration([
38	      [0, 0],
39	      [2, 0],
40	      [1, 1],
41	      [0, 2],
42	      [2, 2],
43	    ]);
44	
45	    expect(result).not.toContainEqual([1, 1]);
46	  });
47	  it("Rule 4 Reproduction: should bring a dead cell with exactly 3 live neighbors to life — (1,1) becomes alive", () => {
48	    // Gen 0: an L-shaped triomino. The dead cell (1,1) is adjacent to all
49	    // three live cells, so it has exactly 3 live neighbours and is born.
50	    const result = nextGeneration([
51	      [0, 0],
52	      [1, 0],
53	      [0, 1],
54	    ]);
55	
56	    expect(result).toContainEqual([1, 1]);
57	  });
58	  it("Block still life: should leave the block unchanged — [(0,0),(1,0),(0,1),(1,1)] → same 4 cells", () => {
59	    // Every cell of a 2x2 block has exactly 3 live neighbours (two
60	    // orthogonal, one diagonal) and survives; no dead cell around it reaches 3.
61	    const block: Cell[] = [
62	      [0, 0],
63	      [1, 0],
64	      [0, 1],
65	      [1, 1],
66	    ];
67	
68	    expect(sorted(nextGeneration(block))).toEqual(sorted(block));
69	  });
70	  it("Blinker: should rotate a vertical blinker to horizontal — [(0,0),(0,1),(0,2)] → [(-1,1),(0,1),(1,1)]", () => {
71	    // The centre (0,1) has exactly 2 live neighbours and survives; the two
